    layer(ctx, .5, -T * 60, 0, () => { for (let i = 0; i < 10; i++) cypress(ctx, i * 150, 1150, 140, '#3E5A4E'); });
    const vy = 1180, off = -(T * 600) % 170; aqueduct(ctx, -300 + off, W + 400, vy, 170, 300, 420, '#D2A97A');
    ctx.fillStyle = '#E8EEF4'; ctx.fillRect(-300, vy - 14, W + 600, 14); ctx.fillStyle = 'rgba(90,220,255,.9)'; ctx.fillRect(-300, vy - 16, W + 600, 4);
    maglev(ctx, 760, vy - 26 + Math.sin(T * 2.5) * 5, 1.15, T, { cars: 3 });
    // silence waves (soft rings)
    for (let k = 0; k < 3; k++) { const p = (T * .7 + k / 3) % 1; ctx.strokeStyle = `rgba(255,255,255,${.35 * (1 - p)})`; ctx.lineWidth = 3; ellipse(ctx, 1000, vy - 70, 60 + p * 200, 30 + p * 100); ctx.stroke(); }
