    ctx.strokeStyle = '#7A4A22'; ctx.lineWidth = 5; ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax, ay - h * .07); ctx.stroke(); circle(ctx, ax, ay - h * .07, 7); ctx.fillStyle = '#E8A46A'; ctx.fill();
