    ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 3; for (let k = 0; k < 14; k++) { const x = 700 + ((k * 137 + T * 30) % 1600), y = 1185 + (k % 5) * 28; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 50, y); ctx.stroke(); }
    // barco de papiro
