// ---------- 4 · oito casas de turfa 13,57–16,87 ----------
const VK_CASAS = [[70, 1060, 170, 120], [300, 1050, 170, 120], [540, 1060, 170, 120], [780, 1050, 170, 120], [-20, 1185, 240, 165], [330, 1180, 240, 165], [680, 1190, 240, 165], [600, 1330, 340, 230]];
